class MakefileManager:
    """manages creation, execution and design of makefiles"""

    def __init__(self, name):
        self.name = name
        self._filename = f"Makefile_{name}"
        self._is_created = False

    def set_filename(self, filename):
        """set the makefile's filename"""
        self._filename = filename
        self._is_created = False

    def create_file(self):
        """create the file"""
        self._is_created = True

    def execute_file(self):
        """execute the makefile"""
        if not self._is_created:
            self.create_file()


class LibRoutine:
    """
    LibRoutine collects and manages all information for a routine in a library.

    # include a backend signature here. The backend can be set from the ADAAs
    backend when the libroutine is created from the routines.
    """

    implementation = "generic"

    def __init__(self, routine, library, dependencies=None):
        self._identifier = routine.name
        self._library = library
        self._dependencies = {}
        self.routine = routine
        if dependencies is not None:
            if isinstance(dependencies, dict):
                for dep in dependencies.values():
                    self.add_dependency(dep)
            else:
                raise ValueError("dependencies must be a dict")

    @property
    def library(self):
        """read-only access to attribute library"""
        return self._library

    @property
    def name(self):
        """read-only access to attribute name"""
        return f"{self.identifier}_{self.implementation}"

    @property
    def identifier(self):
        """read-only access to attribute identifier"""
        return self._identifier

    def create_source_lines(self, **kwargs):
        """create the source code lines"""
        yield ""

    def get_instructions(self):
        """iterate through all instructions"""
        for instruction in (
            self.routine.instruction_group.sorted(lambda x: x["targ_indx"])
            .flatten()
            .instructions
        ):
            yield instruction

    def add_dependency(self, libroutine):
        """add a dependency to a certain libroutine"""
        ident_impl = (libroutine.identifier, libroutine.implementation)
        if ident_impl in self._dependencies:
            return
        self._dependencies[ident_impl] = libroutine

    @property
    def dependencies(self):
        """get all dependencies"""
        yield from self._dependencies.items()

    def get_meta(self):
        """return meta information on the library"""
        return {
            "subroutine_name": self.name,
            "num_instructions": len(self.routine.instruction_group),
            "implementation": self.implementation,
            "identifier": self.identifier,
            "library": self.identifier,
        }


class LibraryManager:
    """
    Library manager class description.

    Used to create, manage, adapt and compile libraries.
    """

    def __init__(self, libname):
        self._libname = libname
        self._libroutines = {}
        self._dependencies = {}
        self._constant_arrays = {}

    @property
    def name(self):
        """read-only access to property name"""
        return self._libname

    @property
    def libroutines(self):
        """generator-access to libroutines"""
        yield from self._libroutines.items()

    def append(self, routine, implementation="default"):
        """append a routine to the library"""
        libroutine = self.to_libroutine(routine, implementation=implementation)
        ident_impl = (libroutine.identifier, libroutine.implementation)
        if ident_impl in self._libroutines:
            raise KeyError(
                f"Routine '{libroutine.name}' already exists in library"
            )
        self._libroutines[ident_impl] = libroutine
        for dep_ident_impl, dep in libroutine.dependencies:
            if dep_ident_impl not in self._dependencies:
                self._dependencies[dep_ident_impl] = dep

    def to_libroutine(self, routine, implementation=None):
        """create a libroutine from the routine"""
        raise NotImplementedError(
            "'to_libroutine' must be implemented by subclasses"
        )

    def create(self):
        """create the library"""

    def create_source_lines(self, **_kwargs):
        """create the source code lines"""
        yield ""

    @property
    def dependencies(self):
        """get all dependencies"""
        yield from self._dependencies.items()

    def add_constant_array(self, arrname, dtype, values):
        """append a constant array to the section"""
        if arrname in self._constant_arrays:
            raise ValueError(f"Constant array '{arrname}' already exists")
        self._constant_arrays[arrname] = (dtype, values)

    def get_meta(self):
        """return meta information on the library"""
        return {
            "library_name": self.name,
        }


class PythonLibraryManager(LibraryManager):
    """
    The object managing a library that then can be loaded to python.
    This is NOT the library itself!
    """


"""
NAMING SCHEME
=============

backends/lib/backend_[backend_specifier]_[implementation].[ending]
e.g.: backend_f90_base.f90, backend_cuda_poly.cu, ...


first to be implemented
-------------------------

linear: one instruction: one scale for one x_i
y_j <- a * x_i

multilinear: one instruction: one scale for one x_i
z_l <- a * x_i * y_j

subroutinecall: call another subroutine
name(*params)


later to be implemted
---------------------

special function: sin, cos, exp, log, snh, csh
sfun_sin y_j <- a_i * [sin, cos, ...](b_i * x_i) + c_i

bivariate multinomial: one instruction <-> combined powers of multiple x_i
z_l <- a_1 x_i,1 ** n_1,1 * x_i,2 ** n_1,2 * ... y_i,1 ** m_1,1 * ... + 

multinomial: one instruction <-> combined powers of multiple x_i
y_j <- a_1 x_i,1 ** n_1,1 * x_i,2 ** n_1,2 * ... + 

polynomial: one instruction <-> powers of one x_i
y_j <- a_1 x_i ** n_1 + ...

monomial: one instruction <-> one power of one x_i
y_j <- a x_i ** n

affine (linear plus a constant): one instruction: one scaled x_i and one offset b
y_j <- a x_i + b

lookup: one instruction: one specific x_i
y_j <- x_i

mask: one instruction: one specific x_i
y_i <- x_i with extras

permutation: one instruction: a pair of i and j, where i is mapped to j
y_j <- x_i with extras


"""


